import React from 'react';
import { Divider } from 'antd';
import { SearchOutlined } from '@ant-design/icons';
import { ProForm, ProFormRadio } from '@ant-design/pro-components';
import { BorderBox, StretchInput } from '@jiovan-labs/ant-buddy-pro';


export default () => {
    const [miniatureType, setMiniatureType] = React.useState<string>('default');

    return (
        <>
            <ProForm
                name='StretchInput_demo.zh-TW'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProFormRadio.Group
                    label='折疊類型'
                    radioType='button'
                    fieldProps={{
                        value: miniatureType,
                        buttonStyle: 'solid',
                        onChange: (event: any) => {
                            setMiniatureType(event.target?.value);
                        }
                    }}
                    options={[
                        { label: '默認', value: 'default' },
                        { label: '自定義', value: 'custom' },
                    ]}
                />
            </ProForm>
            <Divider />
            <div style={{ textAlign: 'right' }}>
                <StretchInput
                    name='foobar'
                    placeholder='請點擊此項'
                    fieldProps={{
                        prefix: <SearchOutlined style={{ cursor: 'pointer' }} />,
                        style: {
                            borderRadius: '16px',
                            width: '50%',
                        }
                    }}
                    miniature={miniatureType !== 'custom' ? undefined : (
                        <BorderBox boundShape='circle' borderAll={true} containerStyle={{ padding: 8 }}>
                            <SearchOutlined />
                        </BorderBox>
                    )}
                    stretchStyle={{
                        borderRadius: '16px',
                        width: '100%',
                    }}
                />
            </div>
        </>
    );
}
