import React from 'react';
import { Divider } from 'antd';
import { ProForm, ProFormRadio, ProFormSwitch } from '@ant-design/pro-components';
import { ServerTuple, ConsoleUtils, type AxisOrientationType } from '@jiovan-labs/ant-buddy-pro';


export default () => {
    const [form] = ProForm.useForm();
    const [layout, setLayout] = React.useState<AxisOrientationType>('vertical');
    const [widthBlock, setWidthBlock] = React.useState<boolean>(true);

    return (
        <>
            <ProForm
                name='ServerTuple_demo.en-US'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProFormRadio.Group
                    label='Layout'
                    radioType='button'
                    fieldProps={{
                        value: layout,
                        buttonStyle: 'solid',
                        onChange: (event: any) => {
                            setLayout(event.target?.value);
                        }
                    }}
                    options={[
                        { label: 'Horizontal', value: 'horizontal' },
                        { label: 'Vertical', value: 'vertical' },
                    ]}
                />
                <ProFormSwitch
                    label='Width Block'
                    checkedChildren='True'
                    unCheckedChildren='False'
                    fieldProps={{
                        checked: widthBlock,
                        onChange: setWidthBlock,
                    }}
                />
            </ProForm>
            <Divider />
            <ProForm
                form={form}
                name='ServerTuple_demo.en-US.Test'
                layout={layout}
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ServerTuple
                    name='server'
                    label='Server'
                    widthBlock={widthBlock}
                    hostProps={{
                        fieldProps: {
                            onChange: () => {
                                const values = form.getFieldsValue(['serverHost', 'serverPort']);
                                ConsoleUtils.logTimestamp(false, false, 'ServerTuple', 'host onChange host/port value = ' + values.serverHost + '/' + values.serverPort);
                            },
                        },
                    }}
                    portProps={{
                        fieldProps: {
                            onChange: () => {
                                const values = form.getFieldsValue(['serverHost', 'serverPort']);
                                ConsoleUtils.logTimestamp(false, false, 'ServerTuple', 'port onChange host/port value = ' + values.serverHost + '/' + values.serverPort);
                            },
                        },
                    }}
                    locale='en_US'
                />
            </ProForm>
        </>
    );
}
