import React from 'react';
import { Divider } from 'antd';
import { ProForm, ProFormRadio, ProFormSelect, ProFormSwitch } from '@ant-design/pro-components';
import { CardTabs, type PaddingSpaceType } from '@jiovan-labs/ant-buddy-pro';
import { type TabPlacement } from '@jiovan-labs/ant-buddy-pro/layout/CardTabs';


export default () => {
    const [tabPlacement, setTabPlacement] = React.useState<TabPlacement>('top');
    const [tabBorder, setTabBorder] = React.useState<boolean>(true);
    const [contentBorder, setContentBorder] = React.useState<boolean>(true);
    const [inkBar, setInkBar] = React.useState<boolean>(true);
    const [presetStyle, setPresetStyle] = React.useState<PaddingSpaceType | false>('padding-md');

    // noinspection DuplicatedCode
    return (
        <>
            <ProForm
                name='CardTabs_demo.zh-CN'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProFormRadio.Group
                    label='Tab 位置'
                    radioType='button'
                    fieldProps={{
                        value: tabPlacement,
                        buttonStyle: 'solid',
                        onChange: (event: any) => {
                            setTabPlacement(event.target?.value);
                        }
                    }}
                    options={[
                        { label: '上', value: 'top' },
                        { label: '下', value: 'bottom' },
                        { label: '左', value: 'start' },
                        { label: '右', value: 'end' },
                        { label: '上-末尾', value: 'top-end' },
                        { label: '下-末尾', value: 'bottom-end' },
                    ]}
                />
                <ProForm.Group>
                    <ProFormSwitch
                        label='标签边框'
                        checkedChildren='是'
                        unCheckedChildren='否'
                        fieldProps={{
                            checked: tabBorder,
                            onChange: setTabBorder,
                        }}
                    />
                    <ProFormSwitch
                        label='内容区边框'
                        checkedChildren='是'
                        unCheckedChildren='否'
                        fieldProps={{
                            checked: contentBorder,
                            onChange: setContentBorder,
                        }}
                    />
                    <ProFormSwitch
                        label='活跃指示条'
                        checkedChildren='是'
                        unCheckedChildren='否'
                        fieldProps={{
                            checked: inkBar,
                            onChange: setInkBar,
                        }}
                    />
                </ProForm.Group>
                <ProFormSelect
                    label='预设样式'
                    placeholder='预设样式'
                    width='md'
                    fieldProps={{
                        allowClear: true,
                        value: presetStyle,
                        options: [
                            { label: 'padding-0', value: 'padding-0' },
                            { label: 'padding-xxs', value: 'padding-xxs' },
                            { label: 'padding-xs', value: 'padding-xs' },
                            { label: 'padding-sm', value: 'padding-sm' },
                            { label: 'padding-md', value: 'padding-md' },
                            { label: 'padding-lg', value: 'padding-lg' },
                            { label: 'False', value: undefined },
                        ],
                        onChange: (value) => {
                            setPresetStyle(value);
                        }
                    }}
                />
            </ProForm>
            <Divider />
            <CardTabs
                tabPlacement={tabPlacement}
                tabBorder={tabBorder}
                contentBorder={contentBorder}
                inkBar={inkBar}
                presetStyle={presetStyle}
                items={new Array(3).fill(null).map((_, i) => {
                    const id = String(i + 1);
                    return {
                        label: `Tab ${id}`,
                        key: id,
                        children: (
                            <>
                                <span>Tab 面板 {id} 的内容</span>
                                <br /><br />
                                <span>Tab 面板 {id} 的内容</span>
                                <br /><br />
                                <span>Tab 面板 {id} 的内容</span>
                            </>
                        ),
                    }
                })}
            />
        </>
    );
}
