import React from 'react';
import { Divider, Empty } from 'antd';
import { ProForm, ProFormRadio, ProFormSwitch } from '@ant-design/pro-components';
import { IconSelect, ConsoleUtils } from '@jiovan-labs/ant-buddy-pro';
import { IconOptionMode } from '@jiovan-labs/ant-buddy-pro/form/IconSelect';
import { type TabPlacement } from '@jiovan-labs/ant-buddy-pro/layout/CardTabs';


export default () => {
    const [optionMode, setOptionMode] = React.useState<IconOptionMode>('icon');
    const [tabPlacement, setTabPlacement] = React.useState<TabPlacement>('top');
    const [themeInkBar, setThemeInkBar] = React.useState<boolean>(true);
    const [sceneInkBar, setSceneInkBar] = React.useState<boolean>(true);
    const [searchBox, setSearchBox] = React.useState<boolean>(true);
    const [tooltipCtrl, setTooltipCtrl] = React.useState<boolean>(false);

    return (
        <>
            <ProForm
                name='IconSelect_demo.zh-CN'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProForm.Group>
                    <ProFormRadio.Group
                        label='选项模式'
                        radioType='button'
                        fieldProps={{
                            value: optionMode,
                            buttonStyle: 'solid',
                            onChange: (event: any) => {
                                setOptionMode(event.target?.value);
                            }
                        }}
                        options={[
                            { label: '图标', value: 'icon' },
                            { label: '文本', value: 'text' },
                        ]}
                    />
                </ProForm.Group>
                <ProFormRadio.Group
                    label='Tab 位置'
                    radioType='button'
                    fieldProps={{
                        value: tabPlacement,
                        buttonStyle: 'solid',
                        disabled: optionMode === 'text',
                        onChange: (event: any) => {
                            setTabPlacement(event.target?.value);
                        }
                    }}
                    options={[
                        { label: '上', value: 'top' },
                        { label: '下', value: 'bottom' },
                        { label: '左', value: 'start' },
                        { label: '右', value: 'end' },
                        { label: '上-末尾', value: 'top-end' },
                        { label: '下-末尾', value: 'bottom-end' },
                    ]}
                />
                <ProForm.Group>
                    <ProFormSwitch
                        label='主题指示条'
                        checkedChildren='是'
                        unCheckedChildren='否'
                        fieldProps={{
                            checked: themeInkBar,
                            disabled: optionMode === 'text',
                            onChange: setThemeInkBar,
                        }}
                    />
                    <ProFormSwitch
                        label='场景指示条'
                        checkedChildren='是'
                        unCheckedChildren='否'
                        fieldProps={{
                            checked: sceneInkBar,
                            disabled: optionMode === 'text',
                            onChange: setSceneInkBar,
                        }}
                    />
                    <ProFormSwitch
                        label='搜索框'
                        checkedChildren='是'
                        unCheckedChildren='否'
                        fieldProps={{
                            checked: searchBox,
                            disabled: optionMode === 'text',
                            onChange: setSearchBox,
                        }}
                    />
                    <ProFormSwitch
                        label='Tooltip 控件'
                        checkedChildren='是'
                        unCheckedChildren='否'
                        fieldProps={{
                            checked: tooltipCtrl,
                            disabled: optionMode === 'text',
                            onChange: setTooltipCtrl,
                        }}
                    />
                </ProForm.Group>
                <Divider />
                <IconSelect
                    name='demoIcon'
                    placeholder='请选择图标'
                    fieldProps={{
                        notFoundContent: (<Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description='无数据'/>),
                        onChange: (value) => {
                            ConsoleUtils.logTimestamp(false, false, 'IconSelect', 'onChange value = ' + value);
                        }
                    }}
                    rules={[
                        {
                            required: true,
                            message: '请输入示例字段',
                        },
                    ]}
                    optionMode={optionMode}
                    themeInkBar={themeInkBar}
                    sceneInkBar={sceneInkBar}
                    tabsProps={{
                        tabPlacement: tabPlacement,
                    }}
                    searchBox={searchBox}
                    tooltipCtrl={tooltipCtrl}
                    locale='zh_CN'
                />
            </ProForm>
        </>
    );
}
